46: // Describe returns a (multi-line) representation of the commit indexes for the
47: // given lookuper.
48: func (c MajorityConfig) Describe(l AckedIndexer) string {
49: 	if len(c) == 0 {
50: 		return "<empty majority quorum>"
51: 	}
52: 	type tup struct {
53: 		id  uint64
54: 		idx Index
55: 		ok  bool // idx found?
56: 		bar int  // length of bar displayed for this tup
57: 	}
58: 
59: 	// Below, populate .bar so that the i-th largest commit index has bar i (we
60: 	// plot this as sort of a progress bar). The actual code is a bit more
61: 	// complicated and also makes sure that equal index => equal bar.
62: 
63: 	n := len(c)
64: 	info := make([]tup, 0, n)
65: 	for id := range c {
66: 		idx, ok := l.AckedIndex(id)
67: 		info = append(info, tup{id: id, idx: idx, ok: ok})
68: 	}
